const sha=b=>crypto.createHash("sha256").update(b).digest("hex"),stable=v=>JSON.stringify(v),mode=s=>s.mode&0o7777;
async function absent(p){try{await fsp.lstat(p);throw Error("PATH_NOT_ABSENT:"+p)}catch(e){if(e.code!=="ENOENT")throw e}}
async function identity(p){const s=await fsp.lstat(p);if(!s.isFile()||s.nlink!==1)throw Error("NON_ORDINARY_FILE:"+p);const b=await fsp.readFile(p);return{dev:String(s.dev),ino:String(s.ino),uid:s.uid,gid:s.gid,mode:mode(s),nlink:s.nlink,bytes:b.length,sha256:sha(b)}}
async function directoryIdentity(p){const s=await fsp.lstat(p);if(!s.isDirectory()||s.isSymbolicLink())throw Error("NON_ORDINARY_DIRECTORY:"+p);return{dev:String(s.dev),ino:String(s.ino),uid:s.uid,gid:s.gid,mode:mode(s),nlink:s.nlink}}
async function ownedDirectoryIdentity(p){const value=await directoryIdentity(p);return{dev:value.dev,ino:value.ino,uid:value.uid,gid:value.gid,mode:value.mode}}
async function treeSnapshot(root){const values=[];const walk=async(rel="")=>{for(const name of(await fsp.readdir(path.join(root,rel))).sort()){const next=path.join(rel,name),p=path.join(root,next),s=await fsp.lstat(p),base={path:next,dev:String(s.dev),ino:String(s.ino),uid:s.uid,gid:s.gid,mode:mode(s),nlink:s.nlink,type:s.isDirectory()?"directory":s.isFile()?"file":s.isSymbolicLink()?"symlink":"other"};if(base.type==="file"){const bytes=await fsp.readFile(p);values.push({...base,bytes:bytes.length,sha256:sha(bytes)})}else{values.push(base);if(base.type==="directory")await walk(next)}}};await walk();return values}
async function noReplaceMove(source,target){await absent(target);if(process.platform==="linux"){execFileSync("/usr/bin/mv",["-T","--no-clobber",source,target]);await absent(source)}else await fsp.rename(source,target)}
async function quarantineOwnedDirectory(p,expected,expectedTree,hooks,label){const quarantine=p+".cleanup-pre-switch",owned=path.join(quarantine,"owned");if(stable(await ownedDirectoryIdentity(p))!==stable(expected)||stable(await treeSnapshot(p))!==stable(expectedTree))throw Error("CONTROL_TREE_CHANGED:"+label);if(hooks?.beforeControlCleanup)await hooks.beforeControlCleanup({path:p,label,expected,expectedTree,quarantine});await fsp.mkdir(quarantine,{mode:0o700});const reservation=await ownedDirectoryIdentity(quarantine);await noReplaceMove(p,owned);if(stable(await ownedDirectoryIdentity(quarantine))!==stable(reservation)||stable(await ownedDirectoryIdentity(owned))!==stable(expected)||stable(await treeSnapshot(owned))!==stable(expectedTree))throw Error("CONTROL_QUARANTINE_MISMATCH:"+label);await fsp.rm(quarantine,{recursive:true});await absent(quarantine);await absent(p)}
async function stdin(){const chunks=[];for await(const chunk of process.stdin)chunks.push(chunk);return Buffer.concat(chunks)}
function decode(raw){let value;try{value=JSON.parse(raw.toString("utf8"))}catch{throw Error("CARRIER_JSON_INVALID")}if(stable(value)+"\n"!==raw.toString("utf8")||value.schemaVersion!=="1.0.0"||stable(value.objects?.map(o=>o.name))!==stable(ORDER))throw Error("CARRIER_NOT_CANONICAL");for(const object of value.objects){const expected=EXPECTED[object.name],bytes=Buffer.from(object.base64,"base64");if(!expected||object.bytes!==expected.bytes||object.sha256!==expected.sha256||object.mode!==expected.mode||bytes.length!==expected.bytes||sha(bytes)!==expected.sha256||bytes.toString("base64")!==object.base64)throw Error("CARRIER_OBJECT_INVALID:"+object.name);object.bytesDecoded=bytes}return value}
async function tree(root){const values=[];const walk=async(rel="")=>{for(const name of(await fsp.readdir(path.join(root,rel))).sort()){const next=path.join(rel,name),s=await fsp.lstat(path.join(root,next));if(s.isSymbolicLink())throw Error("PLACEMENT_SYMLINK:"+next);values.push((s.isDirectory()?"d:":"f:")+next);if(s.isDirectory())await walk(next)}};await walk();return values.sort()}
const EXPECTED_TREE=Object.freeze(["f:placement.receipt.json","f:release-upgrade-executor-3f97a13d.mjs","d:release-candidates","d:release-candidates/candidate-0e1a53c5","f:release-candidates/candidate-0e1a53c5/creator-studio.tar","d:release-candidates/candidate-3f97a13d","f:release-candidates/candidate-3f97a13d/creator-studio.tar"].sort());
async function validate(root){const receipt=JSON.parse(await fsp.readFile(path.join(root,"placement.receipt.json"),"utf8"));if(receipt.schemaVersion!=="1.0.0"||receipt.status!=="PLACED_AWAITING_FORWARD"||receipt.root!==root||stable(await ownedDirectoryIdentity(root))!==stable(receipt.rootIdentity)||stable(await tree(root))!==stable(EXPECTED_TREE))throw Error("PLACEMENT_RECEIPT_INVALID");for(const name of ORDER)if(stable(await identity(path.join(root,name)))!==stable(receipt.objects[name]))throw Error("PLACEMENT_OBJECT_SUBSTITUTED:"+name);return receipt}


async function placeSimple(raw,root=PROD_ROOT,hooks){const carrier=decode(raw),stage=root+".next";await absent(root);await absent(stage);await fsp.mkdir(stage,{mode:0o700});let stageOwned=await ownedDirectoryIdentity(stage),stageTree=await treeSnapshot(stage);try{const objects={};let index=0;for(const object of carrier.objects){const target=path.join(stage,object.name);await fsp.mkdir(path.dirname(target),{recursive:true,mode:0o700});await fsp.writeFile(target,object.bytesDecoded,{flag:"wx",mode:object.mode});await fsp.chmod(target,object.mode);objects[object.name]=await identity(target);stageOwned=await ownedDirectoryIdentity(stage);stageTree=await treeSnapshot(stage);index++;if(hooks?.failPlacementAfterObject===index)throw Error("FIXTURE_PLACEMENT_FAILURE")}const receipt={schemaVersion:"1.0.0",status:"PLACED_AWAITING_FORWARD",root,rootIdentity:stageOwned,carrier:{bytes:raw.length,sha256:sha(raw)},objects},receiptPath=path.join(stage,"placement.receipt.json");await fsp.writeFile(receiptPath,stable(receipt)+"\n",{flag:"wx",mode:0o600});stageTree=await treeSnapshot(stage);await fsp.rename(stage,root);if(stable(await ownedDirectoryIdentity(root))!==stable(stageOwned))throw Error("PLACEMENT_ROOT_RENAME_IDENTITY_CHANGED");const validated=await validate(root);return{...validated,cleanupTree:await treeSnapshot(root)}}catch(error){const exists=await fsp.lstat(stage).then(()=>true,e=>e.code!=="ENOENT"?Promise.reject(e):false);if(exists)await quarantineOwnedDirectory(stage,stageOwned,stageTree,hooks,"placement-stage");throw error}}
async function cleanupPlacedRoot(root,placement,hooks){const verified=await validate(root);if(verified.root!==placement.root||verified.carrier.sha256!==placement.carrier.sha256||stable(verified.objects)!==stable(placement.objects)||stable(await treeSnapshot(root))!==stable(placement.cleanupTree))throw Error("CONTROL_PLACEMENT_CHANGED");await quarantineOwnedDirectory(root,placement.rootIdentity,placement.cleanupTree,hooks,"placed-control-root");return{status:"PRE_SWITCH_CONTROL_CLEANED",rootAbsent:true}}
async function forward(raw,root=PROD_ROOT,hooks){const placement=await placeSimple(raw,root,hooks),executor=path.join(root,ORDER[0]);try{const output=hooks?.exec?await hooks.exec(executor,"forward"):execFileSync(process.execPath,[executor,"forward"],{encoding:"utf8"});return{status:"PLACED_FORWARD_SUCCEEDED_ROLLBACK_RETAINED",placement,executorOutput:JSON.parse(output)}}catch(error){const message=error.stderr?Buffer.from(error.stderr).toString("utf8").trim():error.message,receiptPath=hooks?.runtimeReceipt||RUNTIME_RECEIPT,receiptAbsent=await fsp.lstat(receiptPath).then(()=>false,e=>e.code==="ENOENT");if(message.includes("PRE_SWITCH_CLEAN_TERMINAL")||receiptAbsent){const cleanup=await cleanupPlacedRoot(root,placement,hooks);throw Error("FORWARD_FAILED_PRE_SWITCH_CLEAN_TERMINAL:"+stable(cleanup)+":"+message)}throw Error("FORWARD_FAILED_POST_SWITCH_EXECUTOR_ROLLBACK_REQUIRED_OR_RETAINED:"+message)}}
async function rollback(root=PROD_ROOT){const placement=await validate(root),executor=path.join(root,ORDER[0]),output=execFileSync(process.execPath,[executor,"rollback"],{encoding:"utf8"});return{status:"CONDITIONAL_ROLLBACK_SUCCEEDED",placement,executorOutput:JSON.parse(output)}}
function carrier(objects){return Buffer.from(stable({schemaVersion:"1.0.0",objects:ORDER.map(name=>{const bytes=objects[name],expected=EXPECTED[name];return{name,mode:expected.mode,bytes:bytes.length,sha256:sha(bytes),base64:bytes.toString("base64")}})})+"\n")}
